# views.py - Django REST Framework API for document preview service
import requests
from urllib.parse import urlparse, urljoin
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from django.conf import settings


ALLOWED_SCHEMES = ['http', 'https']
BLOCKED_HOSTS = ['localhost', '127.0.0.1']


class DocumentPreviewAPI(APIView):
    """Fetches document preview from partner services.
    Supports redirect following for CDN-hosted documents."""

    def get(self, request):
        target_url = request.query_params.get('url')
        callback_url = request.query_params.get('callback')

        if not target_url:
            return Response({'error': 'url parameter required'},
                          status=status.HTTP_400_BAD_REQUEST)

        # Validate the URL scheme
        parsed = urlparse(target_url)
        if parsed.scheme not in ALLOWED_SCHEMES:
            return Response({'error': 'Invalid scheme'},
                          status=status.HTTP_400_BAD_REQUEST)

        # Basic host validation
        if parsed.hostname in BLOCKED_HOSTS:
            return Response({'error': 'Blocked host'},
                          status=status.HTTP_403_FORBIDDEN)

        try:
            # Follow redirects to handle CDN routing
            resp = requests.get(target_url, timeout=10, allow_redirects=True)
            content_type = resp.headers.get('Content-Type', '')

            preview_data = {
                'status': resp.status_code,
                'content_type': content_type,
                'content_length': len(resp.content),
                'preview': resp.text[:2048] if 'text' in content_type else None,
                'final_url': resp.url
            }

            # If callback specified, POST results there
            if callback_url:
                callback_parsed = urlparse(callback_url)
                if callback_parsed.scheme in ALLOWED_SCHEMES:
                    requests.post(callback_url, json=preview_data, timeout=5)

            return Response(preview_data)

        except requests.exceptions.Timeout:
            return Response({'error': 'Request timeout'},
                          status=status.HTTP_504_GATEWAY_TIMEOUT)
        except requests.exceptions.RequestException as e:
            return Response({'error': f'Request failed: {str(e)}'},
                          status=status.HTTP_502_BAD_GATEWAY)


class RedirectHandlerAPI(APIView):
    """Handles OAuth/SSO redirects from partner integrations."""

    PARTNER_DOMAINS = ['partner1.example.com', 'cdn.example.com']

    def get(self, request):
        next_url = request.query_params.get('next', '/')
        partner = request.query_params.get('partner')

        if partner and partner in self.PARTNER_DOMAINS:
            redirect_target = f'https://{partner}{next_url}'
        else:
            # Allow relative redirects
            redirect_target = next_url

        # Validate not pointing to internal services
        parsed = urlparse(redirect_target)
        if parsed.hostname and parsed.hostname in BLOCKED_HOSTS:
            return Response({'error': 'Invalid redirect target'},
                          status=status.HTTP_400_BAD_REQUEST)

        from django.http import HttpResponseRedirect
        return HttpResponseRedirect(redirect_target)


class InternalMetricsAPI(APIView):
    """Internal endpoint for Prometheus metrics scraping.
    Only accessible from within the cluster."""

    def get(self, request):
        # This endpoint exposes internal service mesh details
        metrics = {
            'pod_name': settings.POD_NAME if hasattr(settings, 'POD_NAME') else 'unknown',
            'namespace': settings.NAMESPACE if hasattr(settings, 'NAMESPACE') else 'default',
            'service_account_token_path': '/var/run/secrets/kubernetes.io/serviceaccount/token',
            'metadata_endpoint': 'http://169.254.169.254/latest/meta-data/',
            'node_ip': settings.NODE_IP if hasattr(settings, 'NODE_IP') else 'unknown'
        }
        return Response(metrics)
